css:
.aha-logos{
  container:aha-logos / inline-size;
  background:var(--aha-white);
  font-family:var(--aha-font-product);
}
.aha-logos *{box-sizing:border-box}
.aha-logos__track{
  display:flex;align-items:center;justify-content:flex-start;
  gap:240px;width:100%;min-width:100%;
  padding:var(--aha-space-32) 0;
  position:relative;overflow:hidden;
}
.aha-logos__set{
  display:flex;justify-content:space-between;gap:var(--aha-space-32);
  flex:none;width:max-content;min-width:100%;margin:0 0 0 -200px;padding:0;
  list-style:none;will-change:transform;
  animation:aha-logos-loop 20s linear infinite;
}
.aha-logos__item{display:flex;justify-content:space-between;align-items:stretch}
.aha-logos__image{
  display:inline-block;vertical-align:middle;
  max-width:100px;
  filter:saturate(0);
}
/* 40px = track gap 240px minus the set's -200px lead-in: the shift that lands set two exactly where set one began */
@keyframes aha-logos-loop{
  from{transform:translateX(0)}
  to{transform:translateX(calc(-100% - 40px))}
}
@media (prefers-reduced-motion:reduce){
  .aha-logos__set{animation:none}
}
@container aha-logos (width >= 1920px){
  .aha-logos__image{max-width:138px}
}
@container aha-logos (max-width:991px){
  .aha-logos__image{height:50px}
}
@container aha-logos (max-width:479px){
  .aha-logos__image{max-width:none;height:75px}
}
